func:
// backend publishConfigUpdate 의 type 으로 분기
// modules_changed → 기존 modsync_trigger 가 처리 (system-settings)
// house_created/house_changed/house_deleted → 이 flow 가 houseConfig refresh

// payload 가 string 으로 올 수도 있음 (datatype=auto 또는 JSON parse 실패 시)
let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) {
        node.warn('hcs_filter: payload JSON 파싱 실패: ' + e.message);
        return null;
    }
}
if (!data || typeof data !== 'object') return null;

const type = data.type || '';

// houseConfig 영향 type 만 통과
if (!type.startsWith('house_')) {
    return null;  // modules_changed 등은 modsync_trigger 가 처리
}

const farmId = global.get('farmId') || env.get('FARM_ID') || 'farm_0001';
const pcServer = global.get('pcServerUrl') || 'https://api.smartgreen.kr';
const apiKey = global.get('sensorApiKey') || 'smartfarm-sensor-key';

msg.method = 'GET';
msg.url = pcServer + '/api/config/farm/' + farmId + '?_t=' + Date.now();
msg.headers = {
    'x-api-key': apiKey,
    'Cache-Control': 'no-cache',
    'Accept': 'application/json',
};
msg.payload = null;
msg._farmId = farmId;
msg._eventType = type;

node.warn('🏠 houseConfig refresh trigger: ' + type);
node.status({ fill: 'blue', shape: 'dot', text: type + ' ' + new Date().toLocaleTimeString() });
return msg;

// PC backend /config/farm/{farmId} 응답 → global.houseConfig 갱신

let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) {
        node.error('houseConfig 응답 파싱 실패: ' + e.message);
        return null;
    }
}

if (msg.statusCode !== 200) {
    node.error('❌ houseConfig 조회 실패 status=' + msg.statusCode);
    node.status({ fill: 'red', shape: 'dot', text: 'API ' + msg.statusCode });
    return null;
}

const houses = (payload && payload.success && Array.isArray(payload.data)) ? payload.data : [];
if (houses.length === 0) {
    node.warn('houseConfig 빈 응답 — refresh 안 함');
    return null;
}

const farmId = msg._farmId || 'farm_0001';
const eventType = msg._eventType || '?';

// 기존 houseConfig 와 비교
const prev = global.get('houseConfig') || {};
const prevHouses = prev.houses || [];

// houseConfig 구조 (워치독/sensor 폴링이 사용하는 형식)
const newHouseConfig = {
    farmId,
    houses: houses.map(h => ({
        id: h.houseId,
        houseId: h.houseId,
        name: h.houseName || h.name,
        enabled: h.enabled !== false,
        sensors: h.sensors || [],
        devices: h.devices || [],
        configVersion: h.configVersion || 0,
    })),
    configVersion: Math.max(0, ...houses.map(h => h.configVersion || 0)),
};

global.set('houseConfig', newHouseConfig);
global.set('houseConfigUpdatedAt', new Date().toISOString());

// 워치독 캐시 무효화 (modules 변경 시 워치독이 옛 sensor 폴링 안 하도록)
global.set('_watchdogModules', null);

const sensorTotal = houses.reduce((sum, h) => sum + (h.sensors?.length || 0), 0);
const deviceTotal = houses.reduce((sum, h) => sum + (h.devices?.length || 0), 0);

node.status({
    fill: 'green', shape: 'dot',
    text: eventType + ' H:' + houses.length + ' S:' + sensorTotal + ' D:' + deviceTotal
});
node.warn('🏠 houseConfig refresh (' + eventType + '): ' + houses.length + ' houses, ' + sensorTotal + ' sensors, ' + deviceTotal + ' devices');

return null;
